import json,csv,itertools,hashlib
from pathlib import Path
p=Path(__file__).resolve().parents[2];h=p/'Tests/Close';rows=[]
def check(name,value):rows.append(dict(Check=name,Status='PASS' if value else 'FAIL'))
def read(name):return json.loads((h/name).read_text())
c=read('counts.json');status=read('prepublication_status.json');owner=read('owner_decisions.json');functions=read('function_index.json')
reports=list((p/'Reports').glob('HSBI_AUDIT03_CLOSE_*.md'))+list((p/'Reports').glob('HSBI_MONEY_CONTRACT_*.md'))+list((p/'Reports').glob('HSBI_R11_P0_*.md'))
check('12 required report files',len(reports)==12)
check('16 unique canonical decisions awaiting',len(owner)==16 and len({x['DecisionId'] for x in owner})==16 and all(x['OwnerApproval']=='AWAITING_ADMIN_APPROVAL' for x in owner))
check('199 lexical definitions',len(functions)==199)
check('50 inherited ERR priorities',c['ERRORS_TOTAL']==50 and (c['ERRORS_P0'],c['ERRORS_P1'],c['ERRORS_P2'])==(14,31,5))
check('486 document partition',c['TOTAL_DOCUMENTS']==486 and sum(c[x] for x in ('DOCUMENTS_FULLY_REVIEWED','DOCUMENTS_PARTIALLY_REVIEWED','DOCUMENTS_NOT_REVIEWED'))==486)
check('66 formula status partition',sum(c[x] for x in ('FORMULAS_PROVEN_UNDER_ASSUMPTIONS','FORMULAS_CONTRADICTORY','FORMULAS_INVALID','FORMULAS_UNVERIFIED'))==66)
with (h/'fsm_matrix.csv').open() as f:fsm=list(csv.DictReader(f))
axes=('State','Event','Partial','Timeout','Restart');domains=[{r[x] for r in fsm} for x in axes];actual={tuple(r[x] for x in axes) for r in fsm}
check('full union-state Cartesian obligation grid',actual==set(itertools.product(*domains)) and len(actual)==len(fsm))
check('FSM not misrepresented as verified',all(x['ProductionVerification']=='NOT_VERIFIED' for x in fsm))
check('63 model literal cases pass',read('reference_results.json')['Pass']==63 and read('reference_results.json')['Fail']==0)
check('23 header-subset checks preserve 16 failures',len(read('production_subset_results.json')['Rows'])==23 and read('production_subset_results.json')['Fail']==16 and read('production_subset_results.json')['RunExit']==1)
check('8 model mutations killed',read('mutation_results.json')['Killed']==8 and read('mutation_results.json')['Survived']==0)
check('initial survivor evidence preserved',read('mutation_initial_results.json')['Survived']==4)
check('historical rerun saved separately',read('historical_TEST_RESULTS.json')['Pass']==62 and read('historical_TEST_RESULTS.json')['FormattingPass']==3)
check('all unapplied patches syntax check',len(read('patch_checks.json'))==5 and all(x['ExitCode']==0 and x['Applied']==False for x in read('patch_checks.json')))
check('scope file allowlists exist',all((p/f).exists() for pkg in read('r11_allowlist.json') for f in pkg['Files']))
check('no native success claimed',status['MQL5_COMPILE']=='NOT_RUN' and status['MQL5_NATIVE_TESTS']=='NOT_RUN' and status['NATIVE_VERIFIED']=='NO')
check('partial audit and no implementation approval',status['AUDIT_COMPLETENESS']=='PARTIAL' and status['R11_IMPLEMENTATION_ALLOWED']=='NO' and status['ADMIN_DECISIONS_APPROVED']==0)
result=dict(Rows=rows,Pass=sum(x['Status']=='PASS' for x in rows),Fail=sum(x['Status']=='FAIL' for x in rows),FSMDimensions=[len(x) for x in domains],FSMRows=len(fsm),Boundary='Artifact consistency checks only, not semantic completeness or production readiness.')
(h/'artifact_checks.json').write_text(json.dumps(result,indent=2)+'\n');print(result)
raise SystemExit(int(result['Fail']>0))
